package org.apache.parquet.crypto.keytools;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.Collections;
import org.apache.hadoop.conf.Configuration;
import org.apache.hadoop.fs.Path;
import org.apache.parquet.crypto.FileEncryptionProperties;
import org.apache.parquet.crypto.ParquetCryptoRuntimeException;
import org.apache.parquet.hadoop.api.WriteSupport.WriteContext;
import org.apache.parquet.schema.MessageTypeParser;

public class PropertiesDrivenCryptoFactoryGetFileEncryptionPropertiesTests {

  private static final Path OUTPUT_PATH = new Path("file:/tmp/parquet-crypto-test.parquet");

  private final PropertiesDrivenCryptoFactory factory = new PropertiesDrivenCryptoFactory();

  private WriteContext writeContext() {
    return new WriteContext(
        MessageTypeParser.parseMessageType(
            "message test { required binary value (UTF8); }"),
        Collections.emptyMap());
  }

  private Configuration internalKeyMaterialConfiguration() {
    Configuration configuration = new Configuration(false);
    configuration.setBoolean(KeyToolkit.KEY_MATERIAL_INTERNAL_PROPERTY_NAME, true);
    return configuration;
  }

  @Test
  void returnsNullWhenNoEncryptionKeysAreConfigured() {
    Configuration configuration = internalKeyMaterialConfiguration();

    FileEncryptionProperties properties =
        factory.getFileEncryptionProperties(configuration, OUTPUT_PATH, writeContext());

    assertNull(properties);
  }

  @Test
  void createsUniformEncryptionPropertiesWithValidFooterKey() {
    Configuration configuration = internalKeyMaterialConfiguration();
    configuration.set(PropertiesDrivenCryptoFactory.UNIFORM_KEY_PROPERTY_NAME, "uniform-key");

    FileEncryptionProperties properties =
        factory.getFileEncryptionProperties(configuration, OUTPUT_PATH, writeContext());

    assertNotNull(properties);
    assertEquals(16, properties.getFooterKey().length);
    assertNotNull(properties.getFooterKeyMetadata());
    assertTrue(properties.encryptedFooter());
    assertNull(properties.getEncryptedColumns());
  }

  @Test
  void honorsPlaintextFooterConfiguration() {
    Configuration configuration = internalKeyMaterialConfiguration();
    configuration.set(PropertiesDrivenCryptoFactory.UNIFORM_KEY_PROPERTY_NAME, "uniform-key");
    configuration.setBoolean(
        PropertiesDrivenCryptoFactory.PLAINTEXT_FOOTER_PROPERTY_NAME, true);

    FileEncryptionProperties properties =
        factory.getFileEncryptionProperties(configuration, OUTPUT_PATH, writeContext());

    assertNotNull(properties);
    assertFalse(properties.encryptedFooter());
    assertEquals(16, properties.getFooterKey().length);
  }

  @Test
  void acceptsAllSupportedDataKeyLengths() {
    int[] supportedLengths = {16, 24, 32};

    for (int keyLength : supportedLengths) {
      Configuration configuration = internalKeyMaterialConfiguration();
      configuration.set(PropertiesDrivenCryptoFactory.UNIFORM_KEY_PROPERTY_NAME, "uniform-key");
      configuration.setInt(KeyToolkit.DATA_KEY_LENGTH_PROPERTY_NAME, keyLength * 8);

      FileEncryptionProperties properties =
          factory.getFileEncryptionProperties(configuration, OUTPUT_PATH, writeContext());

      assertNotNull(properties);
      assertEquals(keyLength, properties.getFooterKey().length);
    }
  }

  @Test
  void rejectsMissingFooterKeyForNonUniformEncryption() {
    Configuration configuration = internalKeyMaterialConfiguration();
    configuration.set(PropertiesDrivenCryptoFactory.COLUMN_KEYS_PROPERTY_NAME, "column-key");

    ParquetCryptoRuntimeException exception =
        assertThrows(
            ParquetCryptoRuntimeException.class,
            () -> factory.getFileEncryptionProperties(configuration, OUTPUT_PATH, writeContext()));

    assertTrue(exception.getMessage().contains("No footer key configured"));
  }

  @Test
  void rejectsMissingColumnKeysForNonUniformEncryption() {
    Configuration configuration = internalKeyMaterialConfiguration();
    configuration.set(PropertiesDrivenCryptoFactory.FOOTER_KEY_PROPERTY_NAME, "footer-key");

    ParquetCryptoRuntimeException exception =
        assertThrows(
            ParquetCryptoRuntimeException.class,
            () -> factory.getFileEncryptionProperties(configuration, OUTPUT_PATH, writeContext()));

    assertTrue(exception.getMessage().contains("No column keys configured"));
  }

  @Test
  void rejectsFooterKeyAlongsideUniformKey() {
    Configuration configuration = internalKeyMaterialConfiguration();
    configuration.set(PropertiesDrivenCryptoFactory.UNIFORM_KEY_PROPERTY_NAME, "uniform-key");
    configuration.set(PropertiesDrivenCryptoFactory.FOOTER_KEY_PROPERTY_NAME, "footer-key");

    ParquetCryptoRuntimeException exception =
        assertThrows(
            ParquetCryptoRuntimeException.class,
            () -> factory.getFileEncryptionProperties(configuration, OUTPUT_PATH, writeContext()));

    assertTrue(exception.getMessage().contains("footer key configured"));
  }

  @Test
  void rejectsColumnKeysAlongsideUniformKey() {
    Configuration configuration = internalKeyMaterialConfiguration();
    configuration.set(PropertiesDrivenCryptoFactory.UNIFORM_KEY_PROPERTY_NAME, "uniform-key");
    configuration.set(PropertiesDrivenCryptoFactory.COLUMN_KEYS_PROPERTY_NAME, "column-key");

    ParquetCryptoRuntimeException exception =
        assertThrows(
            ParquetCryptoRuntimeException.class,
            () -> factory.getFileEncryptionProperties(configuration, OUTPUT_PATH, writeContext()));

    assertTrue(exception.getMessage().contains("column keys configured"));
  }

  @Test
  void rejectsCompleteColumnEncryptionInUniformMode() {
    Configuration configuration = internalKeyMaterialConfiguration();
    configuration.set(PropertiesDrivenCryptoFactory.UNIFORM_KEY_PROPERTY_NAME, "uniform-key");
    configuration.setBoolean(
        PropertiesDrivenCryptoFactory.COMPLETE_COLUMN_ENCRYPTION_PROPERTY_NAME, true);

    ParquetCryptoRuntimeException exception =
        assertThrows(
            ParquetCryptoRuntimeException.class,
            () -> factory.getFileEncryptionProperties(configuration, OUTPUT_PATH, writeContext()));

    assertTrue(exception.getMessage().contains("uniform encryption mode"));
  }

  @Test
  void rejectsInvalidEncryptionAlgorithm() {
    Configuration configuration = internalKeyMaterialConfiguration();
    configuration.set(PropertiesDrivenCryptoFactory.UNIFORM_KEY_PROPERTY_NAME, "uniform-key");
    configuration.set(
        PropertiesDrivenCryptoFactory.ENCRYPTION_ALGORITHM_PROPERTY_NAME, "NOT_AN_ALGORITHM");

    ParquetCryptoRuntimeException exception =
        assertThrows(
            ParquetCryptoRuntimeException.class,
            () -> factory.getFileEncryptionProperties(configuration, OUTPUT_PATH, writeContext()));

    assertTrue(exception.getMessage().contains("Wrong encryption algorithm"));
  }

  @Test
  void rejectsInvalidDataKeyLength() {
    Configuration configuration = internalKeyMaterialConfiguration();
    configuration.set(PropertiesDrivenCryptoFactory.UNIFORM_KEY_PROPERTY_NAME, "uniform-key");
    configuration.setInt(KeyToolkit.DATA_KEY_LENGTH_PROPERTY_NAME, 160);

    ParquetCryptoRuntimeException exception =
        assertThrows(
            ParquetCryptoRuntimeException.class,
            () -> factory.getFileEncryptionProperties(configuration, OUTPUT_PATH, writeContext()));

    assertTrue(exception.getMessage().contains("Wrong data key length"));
  }

  @Test
  void rejectsNullPathWhenExternalKeyMaterialStorageIsConfigured() {
    Configuration configuration = new Configuration(false);
    configuration.set(PropertiesDrivenCryptoFactory.UNIFORM_KEY_PROPERTY_NAME, "uniform-key");
    configuration.setBoolean(KeyToolkit.KEY_MATERIAL_INTERNAL_PROPERTY_NAME, false);

    ParquetCryptoRuntimeException exception =
        assertThrows(
            ParquetCryptoRuntimeException.class,
            () -> factory.getFileEncryptionProperties(configuration, null, writeContext()));

    assertEquals("Output file path cannot be null", exception.getMessage());
  }
}
